      for (let g = 0; g < 18; g++) { const u = (g + 0.5) / 18; const bx = lerp(600, 2060, u); const pts = []; for (let k = 0; k <= 10; k++) { const v = k / 10; pts.push([lerp(1290 + (u - 0.5) * 120, bx, Math.pow(v, 0.9)) + MG.noise2(g * 3, v * 4) * 18, lerp(280 + Math.abs(u - 0.5) * 120, 1120, v)]); } const west = bx < 1290; MG.fx.ink(x, pts, { width: 9, color: west ? 'rgba(80,36,30,0.45)' : 'rgba(30,14,24,0.4)', taper: [0.6, 0.1] }); MG.fx.ink(x, pts.map((p) => [p[0] - 5, p[1]]), { width: 3, color: west ? 'rgba(255,215,170,0.35)' : 'rgba(200,140,120,0.15)', taper: [0.6, 0.1] }); }
