        ctx.save(); ctx.translate(cx, cy); ctx.scale(1, tilt); ctx.rotate(rot); MG.sprite(ctx, S3.dialTex(), 0, 0, { scale: R / 490 }); const lg = ctx.createLinearGradient(-R, -R, R, R); lg.addColorStop(0, 'rgba(255,240,200,0.28)'); lg.addColorStop(0.5, 'rgba(255,240,200,0)'); lg.addColorStop(1, 'rgba(30,15,10,0.35)'); ctx.fillStyle = lg; ctx.beginPath(); ctx.arc(0, 0, R, 0, MG.TAU); ctx.fill();
